import Link from "next/link";
import { notFound } from "next/navigation";
import { prisma } from "@/core/server/prisma";
import { CmsExerciseDetailsEditor, CmsExerciseTemplateSave } from "@/modules/cms/components/CmsExerciseEditor";
import { CmsLifecycleControls } from "@/modules/cms/components/CmsLifecycleControls";
import { CmsPageShell } from "@/modules/cms/components/CmsPageShell";
import { CmsExerciseLearningLinksManager } from "@/modules/grammar/components/CmsExerciseLearningLinksManager";
import { getCmsExerciseAnalytics, validateExerciseConfiguration } from "@/modules/cms/services/exercise-operations.service";
import { displayAnswer } from "@/modules/lessons/components/lesson-content";

export default async function CmsExercisePage({ params }: { params: Promise<{ exerciseId: string }> }) {
  const exerciseId = (await params).exerciseId;
  const [exercise, grammarTopics] = await Promise.all([
    prisma.exercise.findUnique({
      where: { id: exerciseId },
      include: {
        lessonBlock: { include: { lesson: { select: { id: true, title: true } } } },
        previousVersion: { select: { id: true, question: true } },
        nextVersions: { select: { id: true, question: true, contentStatus: true }, orderBy: { createdAt: "desc" } },
        grammarLinks: { include: { grammarTopic: { select: { id: true, title: true, cefrLevel: true } } } },
        vocabularyLinks: { include: { word: { select: { id: true, lemma: true, cefrLevel: true } } } },
      },
    }),
    prisma.grammarTopic.findMany({ where: { archivedAt: null }, orderBy: [{ cefrLevel: "asc" }, { order: "asc" }, { title: "asc" }], select: { id: true, title: true, cefrLevel: true } }),
  ]);
  if (!exercise) notFound();
  const analytics = await getCmsExerciseAnalytics(exercise.id);
  const configurationIssues = validateExerciseConfiguration(exercise);

  return <CmsPageShell eyebrow="Exercise editor" title={exercise.question} description={`${exercise.engineKey} · ${exercise.type}`} actions={<div className="flex flex-wrap gap-2"><Link href={`/cms/preview/exercises/${exercise.id}`} className="rounded-lg border border-slate-300 px-3 py-2 text-sm font-semibold hover:bg-white">Student preview</Link><Link href={`/cms/revisions?entityType=EXERCISE&entityId=${exercise.id}`} className="rounded-lg border border-slate-300 px-3 py-2 text-sm font-semibold hover:bg-white">History</Link><CmsLifecycleControls entityType="EXERCISE" entityId={exercise.id} status={exercise.contentStatus} compact /></div>}>
    <section className="grid gap-4 sm:grid-cols-4"><article className="rounded-xl border bg-white p-4"><p className="text-sm text-slate-500">Lesson</p><Link href={`/cms/lessons/${exercise.lessonBlock.lesson.id}`} className="mt-1 block font-semibold text-blue-700 hover:underline">{exercise.lessonBlock.lesson.title}</Link></article><article className="rounded-xl border bg-white p-4"><p className="text-sm text-slate-500">Attempts</p><p className="mt-1 font-semibold">{analytics.attempts}</p></article><article className="rounded-xl border bg-white p-4"><p className="text-sm text-slate-500">Accuracy</p><p className="mt-1 font-semibold">{analytics.accuracyPercent}%</p></article><article className="rounded-xl border bg-white p-4"><p className="text-sm text-slate-500">Learners</p><p className="mt-1 font-semibold">{analytics.learners}</p></article></section>
    {configurationIssues.length ? <section className="mt-6 rounded-2xl border border-rose-200 bg-rose-50 p-5"><h2 className="font-bold text-rose-950">Configuration needs attention</h2><ul className="mt-2 list-disc space-y-1 pl-5 text-sm text-rose-900">{configurationIssues.map((issue) => <li key={issue}>{issue}</li>)}</ul></section> : <section className="mt-6 rounded-2xl border border-emerald-200 bg-emerald-50 p-5 text-sm font-semibold text-emerald-900">Configuration check passed.</section>}
    <CmsExerciseDetailsEditor exercise={exercise} />
    <CmsExerciseLearningLinksManager exerciseId={exercise.id} initialTopics={exercise.grammarLinks.map((link) => link.grammarTopic)} initialWords={exercise.vocabularyLinks.map((link) => link.word)} topics={grammarTopics} />
    <CmsExerciseTemplateSave exerciseId={exercise.id} defaultTitle={exercise.question.slice(0, 120)} />
    <section className="mt-6 grid gap-4 lg:grid-cols-2"><article className="rounded-2xl border border-slate-200 bg-white p-5"><h2 className="text-xl font-bold text-slate-950">Performance</h2><dl className="mt-4 grid grid-cols-2 gap-4 text-sm"><div><dt className="text-slate-500">Average score</dt><dd className="mt-1 font-semibold">{analytics.averageScore}</dd></div><div><dt className="text-slate-500">Average time</dt><dd className="mt-1 font-semibold">{analytics.averageTimeSeconds === null ? "—" : `${analytics.averageTimeSeconds}s`}</dd></div><div><dt className="text-slate-500">Hints used</dt><dd className="mt-1 font-semibold">{analytics.hintsUsed}</dd></div><div><dt className="text-slate-500">Correct attempts</dt><dd className="mt-1 font-semibold">{analytics.correct}</dd></div></dl></article><article className="rounded-2xl border border-slate-200 bg-white p-5"><h2 className="text-xl font-bold text-slate-950">Frequent incorrect answers</h2>{analytics.frequentErrors.length ? <ol className="mt-3 space-y-2 text-sm">{analytics.frequentErrors.map((error, index) => <li key={`${displayAnswer(error.answer)}-${index}`} className="rounded-lg bg-slate-50 p-3"><span className="font-semibold">{error.count}×</span> {displayAnswer(error.answer) || "Empty answer"}</li>)}</ol> : <p className="mt-3 text-sm text-slate-500">No incorrect attempts yet.</p>}</article></section>
    {exercise.previousVersion ? <p className="mt-6 text-sm text-slate-600">Version created from <Link href={`/cms/exercises/${exercise.previousVersion.id}`} className="font-semibold text-blue-700 hover:underline">{exercise.previousVersion.question}</Link>.</p> : null}
    {exercise.nextVersions.length ? <section className="mt-4 rounded-xl border border-slate-200 bg-white p-4"><h2 className="font-semibold text-slate-900">Successor versions</h2><ul className="mt-2 space-y-1 text-sm">{exercise.nextVersions.map((version) => <li key={version.id}><Link href={`/cms/exercises/${version.id}`} className="text-blue-700 hover:underline">{version.question}</Link> · {version.contentStatus}</li>)}</ul></section> : null}
  </CmsPageShell>;
}
